function equipmentSymbol(type,x,y,title){
  const label=type==='press'?'V3':type==='attach'?'ATT':'TOOL';
  const color=type==='press'?'#f9d5b0':type==='attach'?'#c5f2cb':'#dcebf3';
  return `<g transform="translate(${x} ${y})"><title>${esc(title)}</title><rect width="28" height="34" rx="2" fill="${color}" stroke="#244c53"/><path d="M4 5H24M4 29H24" stroke="#799196"/><text x="14" y="21" text-anchor="middle" fill="#102c3a" font-size="10" font-weight="800">${label}</text></g>`;
}
function renderLegacyEquipmentDiagram(){
  const rows=model().processes,lanes=new Map();
  rows.forEach((s,i)=>{const lane=Math.max(0,Math.round(((+s.y||60)-60)/94));if(!lanes.has(lane))lanes.set(lane,[]);lanes.get(lane).push({s,i})});
  let width=1000,height=0,parts=[];
  for(const [lane,items] of [...lanes].sort((a,b)=>a[0]-b[0])){
    const top=height+28;let right=70;
    const positions=items.sort((a,b)=>(+a.s.x||0)-(+b.s.x||0)||a.i-b.i).map(item=>{
      const jigs=getJigs(item.s),press=jigs.filter(j=>jigType(j)==='press'),attach=jigs.filter(j=>jigType(j)==='attach'),tools=jigs.filter(j=>jigType(j)==='tool');
      const x=Math.max(right,70+Math.max(0,+item.s.x||0)*1.7),span=Math.max(124,press.length*32+12,(attach.length+tools.length)*32+44);
      right=x+span+12;return{...item,x,span,press,attach,tools};
    });
    const beltWidth=Math.max(930,right-54);width=Math.max(width,right+24);
    parts.push(`<text x="16" y="${top-9}" fill="#627d83" font-size="12">Hàng ${lane+1}</text><rect x="16" y="${top}" width="${beltWidth}" height="72" fill="#00ad51" stroke="#16723e"/><rect x="16" y="${top+23}" width="${beltWidth}" height="25" fill="#c0eec7"/><path d="M34 ${top+36}H${beltWidth+2}" stroke="#71c885" stroke-dasharray="12 12"/>`);
    for(const {s,i,x,span,press,attach,tools} of positions){
      const noTable=positionUsage([s]).positionOnly===1,machine=(norm(s.name).match(/\b(DMC|WLT|VSWR)\b/)||[''])[0],active=s.id===selectedId;
      parts.push(`<g class="equipment-station" data-id="${esc(s.id)}" tabindex="0" role="button" aria-label="${esc((i+1)+'. '+s.name)}"><title>${esc(s.name)} · ${s.mp} MP</title><rect x="${x-8}" y="${top+48}" width="${span+4}" height="142" rx="7" fill="${active?'#e6f8f1':'transparent'}" fill-opacity=".6" stroke="${active?'#087f69':'transparent'}"/>`);
      press.forEach((j,n)=>parts.push(equipmentSymbol('press',x+32*n,top+40,j.name||'Jig Press')));
      const tableX=x+28,tableY=top+83,tableWidth=Math.max(42,span-36);
      if(noTable)parts.push(`<rect x="${tableX}" y="${tableY}" width="${tableWidth}" height="45" fill="#eff5f8" stroke="#1c4657" stroke-width="3"/><text x="${tableX+tableWidth/2}" y="${tableY+19}" text-anchor="middle" font-size="13" font-weight="800">${machine}</text><text x="${tableX+tableWidth/2}" y="${tableY+34}" text-anchor="middle" font-size="10">Không bàn</text>`);
      else parts.push(`<rect x="${tableX}" y="${tableY}" width="${tableWidth}" height="45" rx="2" fill="#fdfbf4" stroke="#8b9283" stroke-width="2"/><path d="M${tableX+5} ${tableY+45}v7M${tableX+tableWidth-5} ${tableY+45}v7" stroke="#586458" stroke-width="3"/>`);
      [...attach,...tools].forEach((j,n)=>parts.push(equipmentSymbol(jigType(j),tableX+4+n*32,tableY+5,j.name||jigType(j))));
      if(+s.mp>0)parts.push(`<g transform="translate(${x+5} ${tableY+18})" fill="#10b9dc" stroke="#096783" stroke-width="1.5"><circle cx="0" cy="-8" r="6"/><path d="M-9 13V5Q-9-1 0-1Q9-1 9 5V13Z"/></g><text x="${x+5}" y="${tableY+46}" text-anchor="middle" font-size="10">${+s.mp} MP</text>`);
      parts.push(`<text x="${x+span/2}" y="${top+150}" text-anchor="middle" font-size="12" font-weight="800">${i+1}${s.critical?' ★':''}</text><text x="${x+span/2}" y="${top+168}" text-anchor="middle" font-size="11">${esc(s.name.length>19?s.name.slice(0,18)+'…':s.name)}</text></g>`);
    }
    height=top+202;
  }
  $('equipmentDiagram').innerHTML=`<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${Math.max(180,height)}" role="img" aria-label="Sơ đồ băng chuyền ${esc(model().name)}">${parts.join('')}</svg>`;
  $('equipmentDiagram').querySelectorAll('.equipment-station').forEach(el=>{el.onclick=()=>select(el.dataset.id);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(el.dataset.id)}}});
}
function readJigRows(){return [...$('jigList').querySelectorAll('.jig-row')].map(row=>({id:row.dataset.jigId||('j'+Date.now()+'-'+row.dataset.index),name:row.querySelector('.jig-name').value.trim(),type:row.querySelector('.jig-type').value,setup:Math.max(0,+row.querySelector('.jig-setup').value||0)}))}
