  $('jigSummary').textContent=jigs.length?`${jigs.length} Jig · tổng setup ${jigs.reduce((n,j)=>n+(+j.setup||0),0).toFixed(1)} phút`:'Chọn loại Jig để tự hiển thị V3 hoặc Jig Attach trên bàn.';
