function renderVersions(){const list=Object.entries(state.models).filter(([,m])=>m.name===model().name).sort((a,b)=>b[1].version.localeCompare(a[1].version));$('versionList').innerHTML=list.map(([,m],i)=>`<div class="version-entry"><b>${esc(m.version==='Imported'?'Phiên bản đầu tiên':m.version)} ${i===0?'<span class="latest">Mới nhất</span>':''}</b><small>${esc(m.note||'Không có ghi chú')}</small></div>`).join('')}
function startDrag(e){
  if(!canEdit()||e.button!==0||e.target.closest('button'))return;
  const el=e.currentTarget,s=model().processes.find(x=>x.id===el.dataset.id),canvas=$('layoutCanvas'),r=canvas.getBoundingClientRect(),startX=e.clientX,startY=e.clientY,ox=e.clientX-r.left-s.x,oy=e.clientY-r.top-s.y;
  let moved=false;el.setPointerCapture(e.pointerId);
  el.onpointermove=ev=>{if(!moved&&Math.hypot(ev.clientX-startX,ev.clientY-startY)<4)return;if(!moved){snapshot();moved=true}
    const rect=canvas.getBoundingClientRect(),limit=canvas.clientWidth-92;
    s.x=Math.max(0,Math.min(limit,Math.round((ev.clientX-rect.left-ox)/30)*30));
    s.y=Math.max(40,Math.min(canvas.clientHeight-110,Math.round((ev.clientY-rect.top-oy)/47)*47));
    el.style.left=s.x+'px';el.style.top=s.y+'px';
  };
  const finish=()=>{el.onpointermove=null;el.onpointerup=null;el.onpointercancel=null;if(moved){selectedId=s.id;renderList();renderInspector();scheduleSave();toast('Đã cập nhật vị trí trạm')}};
  el.onpointerup=finish;el.onpointercancel=finish;
}
