function excelCell(ws,r,c){return ws[XLSX.utils.encode_cell({r,c})]?.v}
function excelNumber(value){if(value===null||value===undefined||String(value).trim()===''||typeof value==='boolean')return null;const n=typeof value==='number'?value:Number(String(value).replace(',','.'));return Number.isFinite(n)?n:null}
function excelCategory(name){const value=norm(name);if(value==='IQC')return'KIỂM TRA ĐẦU VÀO';if(value.includes('OQC'))return'KIỂM TRA ĐẦU RA';if(value.includes('LASER WELD'))return'HÀN LASER';if(value.includes('VISION')||/\b(WLT|VSWR|WPT|TEST|CHECK)\b/.test(value))return'TEST/KIỂM TRA';if(value.includes('CLEAN'))return'LÀM SẠCH';if(value.includes('METAL SHEET'))return'METAL SHEET';if(value.includes('ROLLING'))return'ROLLING';if(value.includes('AIR VENT'))return'AIRVENT';if(value.includes('VINYL'))return'DÁN VINYL BẢO VỆ';return'DÁN & ÉP'}
function parseLayoutWorksheet(ws,sheetName){
  const range=XLSX.utils.decode_range(ws['!ref']||'A1:A1'),blocks=[],ignored=new Set(['MODEL','TYPE','LINE','LEADER','DKN','SUPPORT','TOTAL MP','QC','TOTAL','PROCESS','TT AVG','MP','NHAN VIEN','ATTACH','DINO','WLT']);
  for(let r=range.s.r;r<=range.e.r-2;r++){const items=[];for(let c=range.s.c;c<=range.e.c;c++){const raw=excelCell(ws,r,c),name=typeof raw==='string'?raw.replace(/\s+/g,' ').trim():'';if(!name||name.startsWith('=')||ignored.has(norm(name)))continue;const time=excelNumber(excelCell(ws,r+1,c)),mp=excelNumber(excelCell(ws,r+2,c));if(time===null||mp===null||time<0||time>300||mp<0||mp>30)continue;const no=excelNumber(excelCell(ws,r-1,c));items.push({name,time,mp,no:no&&no>0&&no<300?Math.round(no):null,col:c})}if(items.length>=3){const median=values=>[...values].sort((a,b)=>a-b)[Math.floor(values.length/2)];if(median(items.map(x=>x.time))<=3&&median(items.map(x=>x.mp))>3)for(const item of items)[item.time,item.mp]=[item.mp,item.time];blocks.push({row:r,items})}}
  if(!blocks.length)throw new Error(`Không tìm thấy bảng Công đoạn / T/T / MP trong ${sheetName}.`);
  const deduped=[],seen=new Set();for(const [blockIndex,block] of blocks.entries()){const ordered=block.items.sort((a,b)=>a.col-b.col);for(const [columnIndex,item] of ordered.entries()){const key=(item.no||'')+'|'+norm(item.name);if(seen.has(key))continue;seen.add(key);deduped.push({...item,block:blockIndex,columnIndex})}}
  deduped.forEach((item,index)=>{if(!item.no)item.no=index+1});deduped.sort((a,b)=>a.no-b.no||a.block-b.block||a.col-b.col);
  const modelName=sheetName.replace(/^\s*layout\s*/i,'').replace(/\s+/g,' ').trim();let line=1,type=/block/i.test(modelName)?'block':'normal';
  for(let r=range.s.r;r<=range.e.r;r++)for(let c=range.s.c;c<=range.e.c;c++){const label=norm(excelCell(ws,r,c));if(label==='LINE'){const n=excelNumber(excelCell(ws,r+2,c));if(Number.isInteger(n)&&n>0)line=n}if(label==='TYPE'){const value=String(excelCell(ws,r+2,c)||'').trim().toLowerCase();if(value)type=value.includes('block')?'block':'normal'}}
  return{modelName,line,type,items:deduped}
}
function closestExistingModel(name){const entries=Object.entries(state.models).filter(([,m])=>norm(m.name)===norm(name));return entries.find(([,m])=>m.isLatest)||entries.at(-1)||null}
function resolveImportConflict(conflicts){return new Promise(resolve=>{const dialog=$('importConflictDialog');$('importConflictBody').innerHTML=conflicts.map(({parsed,base,data})=>{const old=calculateMetrics(base.processes||[]),fresh=calculateMetrics(data.processes);return `<tr><td><b>${esc(parsed.modelName)}</b></td><td>${base.processes?.length||0} → <b>${data.processes.length}</b></td><td>${old.neck.toFixed(2)}s → <b>${fresh.neck.toFixed(2)}s</b></td><td>${(old.lob*100).toFixed(1)}% → <b>${(fresh.lob*100).toFixed(1)}%</b></td></tr>`}).join('');const finish=value=>{dialog.close();resolve(value)};$('overwriteImportBtn').onclick=()=>finish('overwrite');$('newVersionImportBtn').onclick=()=>finish('new');$('cancelImportBtn').onclick=()=>finish(null);dialog.oncancel=e=>{e.preventDefault();finish(null)};dialog.showModal()})}
async function importExcelWorkbook(file){
  if(!canEdit())return toast('Bạn không có quyền nhập dữ liệu.');if(!window.XLSX)throw new Error('Chưa tải được bộ đọc Excel. Hãy tải lại trang.');const button=$('importBtn'),oldText=button.textContent;button.disabled=true;button.textContent='Đang đọc file Excel…';
  try{const workbook=XLSX.read(await file.arrayBuffer(),{type:'array',cellStyles:true,cellFormula:true,cellDates:true}),known=new Set(Object.values(state.models).map(m=>norm(m.name))),sheets=workbook.SheetNames.filter(name=>/^\s*layout\b/i.test(name)||known.has(norm(name)));if(!sheets.length)throw new Error('Không tìm thấy sheet “Layout…” hoặc sheet trùng tên Model.');snapshot();const stamp=new Date(file.lastModified||Date.now()),version=`Excel ${stamp.toLocaleDateString('vi-VN')} ${stamp.toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'})}`,candidates=[];
    for(const sheetName of sheets){button.textContent=`Đang phân tích ${sheetName}…`;let parsed;try{parsed=parseLayoutWorksheet(workbook.Sheets[sheetName],sheetName)}catch{continue}const previousEntry=closestExistingModel(parsed.modelName),base=previousEntry?previousEntry[1]:{name:parsed.modelName,processes:[]},byName=new Map((base.processes||[]).map(s=>[norm(s.name),s]));const processes=parsed.items.map((item,index)=>{const old=byName.get(norm(item.name)),welding=norm(item.name).includes('LASER WELD')||norm(item.name).includes('HAN LASER'),station=p(old?.id||`xl-${Date.now()}-${index}`,item.name,item.time,item.mp,old?.category||excelCategory(item.name),item.mp===0);station.stt=item.no||index+1;station.side=welding?'HEAD':item.block===0?'TOP':'BOTTOM';station.slotIndex=Math.max(1,Math.min(27,item.columnIndex+1));station.isActive=old?.isActive!==false;station.x=(station.slotIndex-1)*60;station.y=60+item.block*94;station.excelBlock=item.block;station.excelColumn=item.col;station.excelNo=item.no;station.jigs=structuredClone(old?.jigs||[]);station.critical=!!old?.critical;station.multiSkills=structuredClone(old?.multiSkills||[]);station.skill25=!!old?.skill25;station.skill40=!!old?.skill40;station.tags=structuredClone(old?.tags||[]);station.layoutObjects={};return station});const data={...structuredClone(base),name:parsed.modelName,version,line:parsed.line,type:parsed.type,processes,sourceSheet:sheetName,excelLayoutApplied:true,isLatest:true,note:`Cập nhật tự động từ ${file.name} · ${sheetName}`};candidates.push({sheetName,parsed,previousEntry,base,data})}
    if(!candidates.length)throw new Error('Không tìm thấy bảng công đoạn hợp lệ trong file.');const conflicts=candidates.filter(c=>c.previousEntry),mode=conflicts.length?await resolveImportConflict(conflicts):'new';if(!mode)return toast('Đã hủy Import Excel.');const imported=[];let nextKey='';
    for(const candidate of candidates){button.textContent=`Đang cập nhật ${candidate.sheetName}…`;const overwrite=mode==='overwrite'&&candidate.previousEntry,id=overwrite?candidate.previousEntry[0]:`${candidate.parsed.modelName}::${version}::${Date.now()}-${imported.length}`,data=candidate.data;data.version=overwrite?candidate.base.version:version;data.note=`${overwrite?'Ghi đè':'Tạo phiên bản mới'} từ ${file.name} · ${candidate.sheetName}`;try{await request('./api/layouts',{method:'POST',body:JSON.stringify({id,data,isLatest:true})})}catch{}for(const entry of Object.values(state.models))if(norm(entry.name)===norm(data.name))entry.isLatest=false;state.models[id]=data;imported.push({sheetName:candidate.sheetName,count:data.processes.length});if(!nextKey||norm(model().name)===norm(data.name))nextKey=id}
    currentKey=nextKey;selectedId=null;persistLocal();renderAll();toast(`${mode==='overwrite'?'Đã ghi đè':'Đã tạo phiên bản mới cho'} ${imported.length} layout`)
  }finally{button.disabled=false;button.textContent=oldText}
}
